static void clear_depth(ZBuffer *zb, GLint z) {
  g_depth_clears++;
  const Box area = g_z_valid && z == g_clear_z ? g_z_box : whole_canvas();
  for (int y = area.y0; y <= area.y1; y++)
    fill_pixels((uint16_t *)(zb->zbuf + y * zb->xsize) + area.x0, (uint16_t)z,
                area.x1 - area.x0 + 1);
