  TEST_ASSERT_EQUAL_INT('b', events[0].kind);
  TEST_ASSERT_EQUAL_INT('r', events[1].kind);
  TEST_ASSERT_EQUAL_INT(40, events[1].y);
  TEST_ASSERT_EQUAL_INT(4, events[1].x0);
